INSERT INTO public.product VALUES
	(1, 'Brazilian - Organic', 'It''s like Carnival in a cup. Clean and smooth.', 18.00, 1),
	(2, 'Our Old Time Diner Blend', 'Our packed blend of beans that is reminiscent of the cup of coffee you used to get at a diner. ', 18.00, 2),
	(3, 'Espresso Roast', 'Our house blend for a good espresso shot.', 14.75, 3),
	(4, 'Primo Espresso Roast', 'Our premium single source of hand roasted beans.', 20.45, 3),
	(5, 'Columbian Medium Roast', 'A smooth cup of coffee any time of day. ', 15.00, 4),
	(6, 'Ethiopia', 'From the home of coffee.', 21.00, 4),
	(7, 'Jamacian Coffee River', 'Ya man, it will start your day off right. ', 19.75, 5),
	(8, 'Civet Cat', 'The most expensive coffee in the world, the cats do all the work. ', 45.00, 5),
	(9, 'Organic Decaf Blend', 'Our blend of hand picked organic beans that have been naturally decaffinated. ', 28.00, 6),
	(10, 'Guatemalan Sustainably Grown', 'Green beans you can roast yourself. ', 10.00, 7),
	(11, 'Lemon Grass', 'You will think you are Thailand as you sip your cuppa. ', 8.95, 8),
	(12, 'Peppermint', 'Cool and refreshing to help calm your nerves. ', 8.95, 8),
	(13, 'English Breakfast', 'The traditional cup to start your day.', 8.95, 9),
	(14, 'Earl Grey', 'A full leaf of Orange Pekoe blended with organic oil of bergamot.', 8.95, 9),
	(15, 'Serenity Green Tea', 'Mountain grown and harvested at the optimal time. ', 9.25, 10),
	(16, 'Traditional Blend Chai', 'A traditional blend.', 8.95, 11),
	(17, 'Morning Sunrise Chai', 'Fair trade and organic and has a warm finish. ', 9.50, 11),
	(18, 'Spicy Eye Opener Chai', 'A spicier blend to awaken your taste buds.', 10.95, 11),
	(19, 'Dark chocolate', 'This drinking chocolate is smooth and creamy.', 6.40, 12),
	(20, 'Sustainably Grown Organic', 'Certified organic containing the highest quality ingredients. ', 7.60, 13),
	(21, 'Chili Mayan', 'Fragrant with spices, this is the most flavourful drinking chocolate you will find.', 13.33, 12),
	(22, 'Our Old Time Diner Blend Sm', 'An honest cup a coffee.', 2.00, 14),
	(23, 'Our Old Time Diner Blend Rg', 'An honest cup a coffee.', 2.50, 14),
	(24, 'Our Old Time Diner Blend Lg', 'An honest cup a coffee.', 3.00, 14),
